<script setup>
import {computed,ref,watch} from 'vue'
import {parseTerm,unifySteps,formatTheta,unificationExamples} from '../services/predicate-terms.mjs'
import SimulationControls from './SimulationControls.vue'
import PredicateCode from './PredicateCode.vue'
const preset=ref('nested'),left=ref(unificationExamples.nested.left),right=ref(unificationExamples.nested.right),active=ref([left.value,right.value]),step=ref(0),error=ref('')
const trace=computed(()=>Array.from(unifySteps(parseTerm(active.value[0]),parseTerm(active.value[1])))),state=computed(()=>trace.value[Math.min(step.value,trace.value.length-1)]),key=computed(()=>JSON.stringify(active.value)),theta=computed(()=>Object.entries(formatTheta(state.value.theta)))
watch(key,()=>step.value=0);watch(preset,()=>{const p=unificationExamples[preset.value];left.value=p.left;right.value=p.right;apply()})
function apply(){try{Array.from(unifySteps(parseTerm(left.value),parseTerm(right.value)));active.value=[left.value,right.value];error.value=''}catch(e){error.value=e.message}}
const message=computed(()=>{const s=state.value;if(s.phase==='success')return 'Hợp nhất thành công. Phép thế trả về làm hai hạng thức đầu vào giống nhau về cú pháp.';if(s.phase==='occurs')return `Thất bại do kiểm tra xuất hiện: ?${s.variable} có trong ${s.term}. Không có hạng thức hữu hạn thỏa phép thế này.`;if(s.phase==='failure')return 'Không hợp nhất được vì tên hằng, tên hàm hoặc số đối số khác nhau. Đây là kết luận cú pháp, không chứng minh hai đối tượng khác nhau trong mọi mô hình.';if(s.phase==='bind')return `Thêm ?${s.variable} ↦ ${s.term}, sau đó truyền phép thế vào các ràng buộc đã có.`;if(s.phase==='equation')return `Xét phương trình ${s.left} = ${s.right} sau khi áp dụng phép thế hiện tại.`;if(s.phase==='decompose')return 'Hai đầu hàm cùng tên và số đối số. Thay bằng các phương trình đối số tương ứng.';if(s.phase==='delete')return 'Hai vế đã giống nhau, bỏ phương trình này.';return 'Biến viết dạng ?x. Hằng và hàm là ký hiệu cú pháp. Mọi xuất hiện cùng tên biến trong hai đầu vào được hiểu là cùng một biến.'})
</script>
<template><section class="math-lab predicate-unify" aria-label="Mô phỏng hợp nhất hạng thức"><label>Trường hợp<select v-model="preset"><option v-for="(p,k) in unificationExamples" :key="k" :value="k">{{ p.title }}</option></select></label><div class="unify-input"><label>Hạng thức thứ nhất<input v-model="left" spellcheck="false"></label><label>Hạng thức thứ hai<input v-model="right" spellcheck="false"></label><button type="button" @click="apply">Hợp nhất đầu vào</button></div><p v-if="error" role="alert">{{ error }}</p><SimulationControls v-model="step" :max="trace.length-1" :reset-key="key"/><div class="unify-state"><article><h4>Phương trình còn chờ</h4><p v-for="([a,b],i) in state.equations" :key="i" class="term-row">{{ a }} = {{ b }}</p><p v-if="!state.equations.length">Không còn phương trình chờ.</p></article><article><h4>Phép thế hiện tại</h4><p v-for="([v,t]) in theta" :key="v" class="term-row">{{ v }} ↦ {{ t }}</p><p v-if="!theta.length">Phép thế rỗng.</p></article></div><p class="predicate-status" role="status">{{ message }}</p><details><summary>Phạm vi biến và kết quả</summary><p>Hai mệnh đề độc lập cần được đổi tên biến trước khi hợp nhất để tránh trùng tên. Bộ xem không tự đổi tên vì cũng cần minh họa trường hợp một biến thật sự xuất hiện nhiều lần.</p><p>Ví dụ Knows(John, ?x) và Knows(?x, Elizabeth) thất bại khi dùng cùng biến. Nếu biến của mệnh đề thứ hai được đổi thành ?x17, phép hợp nhất thành công.</p><p>Hợp nhất xử lý hạng thức hữu hạn và luôn kiểm tra xuất hiện sau khi truyền phép thế. Phép thế ngữ nghĩa của biến lượng từ phải tránh bắt biến, không dùng bộ thay thế hạng thức này trực tiếp lên một công thức có lượng từ.</p></details><PredicateCode name="unifySteps" :phase="state.phase"/></section></template>
<style scoped>
.predicate-unify{min-width:0}.predicate-unify label{display:grid;gap:6px;font:var(--fs-small)/1.7 var(--font-ui)}.predicate-unify :is(input,select,button){min-width:0;max-width:100%;min-height:44px;padding:8px;border:1px solid var(--control);border-radius:var(--radius);background:var(--paper);color:var(--ink);font:inherit}.unify-input{display:grid;gap:12px;margin:16px 0}.unify-input input{font:14px var(--font-code);width:100%}.unify-input button{justify-self:start;cursor:pointer}.unify-state{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.unify-state article{padding:12px;border:1px solid var(--rule);border-radius:var(--radius);background:var(--paper);min-width:0}.unify-state h4{font:600 var(--fs-small)/1.6 var(--font-ui)}.term-row{font:14px/1.8 var(--font-code);overflow-wrap:anywhere}.predicate-status{padding:12px;border-left:3px solid var(--tim);background:var(--tim-soft)}summary{min-height:44px;cursor:pointer}:is(input,select,button,summary):focus-visible{outline:3px solid var(--tim);outline-offset:3px}@media(max-width:600px){.unify-state{grid-template-columns:1fr}}
</style>
